/// Display title for a DX theme name.
pub fn dx_theme_title(name: &str) -> Option<&'static str> {
    DX_THEME_NAMES.iter().position(|n| *n == name).map(|i| DX_THEME_TITLES[i])
}

/// Build the pager Theme for a DX theme name (dark variant).
